// The session cookie (_producthunt_session / a __Secure-* next-auth token) is HttpOnly, so
// document.cookie CANNOT see it — gating on it would report a live session as logged out.
// Order of evidence: (a) the page's own embedded state, (b) a signed-in-only header control.
let why;
try {
  const el = document.getElementById('__NEXT_DATA__');
  if (el && el.textContent) {
    const root = JSON.parse(el.textContent);
    const seen = new Set(); const stack = [root];
    while (stack.length) {
      const n = stack.pop();
      if (!n || typeof n !== 'object' || seen.has(n)) continue;
      seen.add(n);
      for (const k of Object.keys(n)) {
        const v = n[k];
        if ((k === 'viewer' || k === 'currentUser' || k === 'me') && v && typeof v === 'object' && (v.username || v.id)) {
          return {signed_in: true, as: v.username || v.name || undefined, why: '__NEXT_DATA__.' + k};
        }
        if (v && typeof v === 'object') stack.push(v);
      }
    }
    why = '__NEXT_DATA__ present but names no viewer';
  }
} catch (e) { why = '__NEXT_DATA__ parse failed: ' + e.message; }
const mine = document.querySelector('header a[href^="/@"], [data-test="header-user-menu"], [data-test="user-menu"], header a[href="/my/products"]');
if (mine) {
  const href = (mine.getAttribute && mine.getAttribute('href')) || '';
  return {signed_in: true, as: href.startsWith('/@') ? href.slice(2) : undefined, why: 'signed-in-only header control'};
}
const wall = document.querySelector('a[href*="/sign_in"], a[href*="/login"], [data-test="header-signin"]');
return {signed_in: false, why: why || (wall ? 'sign-in control in the header' : 'no signed-in header control found')};
